        collapseButton.title = collapsed ? '展开控制条' : '收起到侧边栏';
        collapseButton.setAttribute('aria-label', collapseButton.title);
      };
      var setCollapsed = function(collapsed, side, y) {
        anchor.setAttribute('data-collapsed', collapsed ? 'true' : 'false');
        if (collapsed) {
          dockCollapsed(anchor, side || getNearestSide(anchor), y);
          window.requestAnimationFrame(function() {
            dockCollapsed(anchor, anchor.getAttribute('data-side'), y);
            syncCollapseButton();
            persistCollapsedState(anchor);
          });
        } else {
          window.requestAnimationFrame(function() {
            restoreExpandedPosition(anchor);
            syncCollapseButton();
            persistCollapsedState(anchor);
            persistPosition(anchor);
          });
        }
        syncCollapseButton();
      };
      collapseButton.onclick = function(event) {
        event.stopPropagation();
        var collapsed = anchor.getAttribute('data-collapsed') === 'true';
        if (collapsed) {
          setCollapsed(false);
        } else {
          setCollapsed(true, getNearestSide(anchor));
        }
      };
      var dragState = null;
      handle.addEventListener('pointerdown', function(event) {
        if (anchor.getAttribute('data-collapsed') === 'true') return;
        dragState = {
          offsetX: event.clientX - anchor.offsetLeft,
          offsetY: event.clientY - anchor.offsetTop,
        };
        shell.setAttribute('data-dragging', 'true');
        handle.setPointerCapture(event.pointerId);
        event.preventDefault();
      });
      handle.addEventListener('pointermove', function(event) {
        if (!dragState) return;
        applyPosition(anchor, event.clientX - dragState.offsetX, event.clientY - dragState.offsetY);
        syncCollapseButton();
      });
      var stopDrag = function(event) {
        if (!dragState) return;
        dragState = null;
        shell.setAttribute('data-dragging', 'false');
        try {
          handle.releasePointerCapture(event.pointerId);
        } catch (error) {}
        persistPosition(anchor);
        persistCollapsedState(anchor);
      };
      handle.addEventListener('pointerup', stopDrag);
      handle.addEventListener('pointercancel', stopDrag);
      window.addEventListener('resize', function() {
        if (anchor.getAttribute('data-collapsed') === 'true') {
          dockCollapsed(anchor, anchor.getAttribute('data-side'), anchor.offsetTop);
          syncCollapseButton();
          persistCollapsedState(anchor);
        } else {
          applyPosition(anchor, anchor.offsetLeft, anchor.offsetTop);
          syncCollapseButton();
          persistPosition(anchor);
        }
      });
      shell.appendChild(handle);
      actions.appendChild(button);
      actions.appendChild(refreshButton);
      actions.appendChild(switchButton);
      shell.appendChild(actions);
      shell.appendChild(collapseButton);
      anchor.appendChild(shell);
      document.body.appendChild(anchor);
      syncGatewayTheme(anchor);
      ensureGatewayThemeObserver();
      anchor.setAttribute('data-collapsed', 'false');
      setAnchorSide(anchor, getNearestSide(anchor));
      restorePosition(anchor);
      var savedCollapsed = readCollapsedState();
      if (savedCollapsed && savedCollapsed.collapsed === true) {
        setCollapsed(true, savedCollapsed.side, savedCollapsed.y);
      } else {
        syncCollapseButton();
      }
    };
    if (document.readyState === 'complete') {
      mount();
    } else {
      window.addEventListener('load', mount, { once: true });
    }
    setInterval(mount, 2000);
  }
})();</script>
